{
  "implementation": "def solve(case):
    # Extract fields
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']

    # Validate
    if not nodes:
        raise ValueError("Empty nodes list")
    for n in nodes:
        if n not in core:
            raise ValueError(f"Missing core distance for node {n}")
    n_nodes = len(nodes)

    # Build edges list: [weight, node1, node2] with canonical order
    edges = []
    for a, b, d in distances:
        if a not in core or b not in core:
            raise ValueError(f"Unknown node in distance pair: {a}, {b}")
        w = max(core[a], core[b], d)
        if a < b:
            u, v = a, b
        else:
            u, v = b, a
        edges.append((w, u, v))

    # Sort deterministically: by weight, then u, then v
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find structure
    parent = {node: node for node in nodes}
    size = {node: 1 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if size[rx] < size[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        size[rx] += size[ry]
        return True

    mst_edges = []
    total_weight = 0.0
    edges_used = 0

    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            edges_used += 1
            if edges_used == n_nodes - 1:
                break

    if edges_used != n_nodes - 1:
        raise ValueError("Graph is disconnected, cannot build MST")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }"
}
